import { useState } from "react";
import { useAuth } from "../../context/AuthContext";
import { useOrders } from "../../context/OrderContext";

export default function UserPanel() {
  const { user, logout } = useAuth();
  const { orders, placeOrder } = useOrders();

  const menu = [
    { id: 1, name: "Idli & Sambar", price: 35 },
    { id: 2, name: "Masala Dosa", price: 45 },
    { id: 3, name: "Veg Puff", price: 20 },
    { id: 4, name: "Veg Thali", price: 80 },
  ];

  const [cart, setCart] = useState([]);

  function addToCart(item) {
    const found = cart.find((c) => c.id === item.id);
    if (found) {
      setCart(cart.map(c => c.id === item.id ? { ...c, qty: c.qty + 1 } : c));
    } else {
      setCart([...cart, { ...item, qty: 1 }]);
    }
  }

  function handlePlaceOrder() {
    if (cart.length === 0) return;

    const total = cart.reduce((s, i) => s + i.price * i.qty, 0);
    placeOrder({
      user: user.username,
      items: cart.map(i => `${i.name} x${i.qty}`).join(", "),
      amount: total,
    });

    setCart([]);
    alert("Demo payment successful. Order placed.");
  }

  return (
    <div className="app-shell">
      <header>
        <h2>User Dashboard</h2>
        <button className="btn btn-outline" onClick={logout}>Logout</button>
      </header>

      <section className="card">
        <h3>Menu</h3>
        {menu.map(item => (
          <div key={item.id} className="menu-card">
            {item.name} – ₹{item.price}
            <button className="btn btn-primary btn-sm" onClick={() => addToCart(item)}>Add</button>
          </div>
        ))}
      </section>

      <section className="card">
        <h3>Cart</h3>
        {cart.map(i => (
          <div key={i.id}>{i.name} x {i.qty}</div>
        ))}
        <button className="btn btn-primary" onClick={handlePlaceOrder}>
          Place Order (Demo Payment)
        </button>
      </section>

      <section className="card">
        <h3>My Orders</h3>
        {orders
          .filter(o => o.user === user.username)
          .map(o => (
            <div key={o.id}>
              {o.id} | ₹{o.amount} | {o.status}
            </div>
          ))}
      </section>
    </div>
  );
}
